WITH latest_match AS (SELECT s.id, s.device, s.browser, s.country, top1.page, top1.web_event_event_type FROM sessions s LEFT JOIN LATERAL (SELECT c.page, c.event_type AS web_event_event_type FROM web_events c WHERE c.session_id = s.id ORDER BY c.duration_sec DESC, c.id DESC LIMIT 1) top1 ON TRUE), not_flagged AS (SELECT s.* FROM latest_match s WHERE NOT EXISTS (SELECT 1 FROM web_events x WHERE x.session_id = s.id AND x.page IN ('/home', '/search'))), cleaned AS (SELECT id, device, browser, country, page, web_event_event_type, INITCAP(TRIM(web_event_event_type)) AS web_event_event_type_title FROM not_flagged WHERE country IS NOT NULL), valid AS (SELECT *, CASE WHEN page = '/product' THEN 1 ELSE 0 END AS is_product FROM cleaned WHERE page IS NOT NULL), scored AS (SELECT *, MIN(is_product) OVER (PARTITION BY device) AS device_min_is_product, NTILE(10) OVER (PARTITION BY web_event_event_type ORDER BY is_product DESC, id) AS is_product_bucket FROM valid WHERE is_product BETWEEN 58 AND 61), enriched AS (SELECT id, country, web_event_event_type, web_event_event_type_title, LAG(is_product, 1) OVER (PARTITION BY country ORDER BY device_min_is_product, id) AS prev_is_product, AVG(is_product_bucket) OVER w_grp AS is_product_bucket_avg_5_prior, AVG(is_product) OVER (PARTITION BY web_event_event_type ORDER BY is_product_bucket, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS is_product_avg_2_prior, AVG(device_min_is_product) OVER (PARTITION BY device ORDER BY is_product_bucket, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS device_min_is_product_avg_6, ROUND(is_product_bucket / SUM(is_product_bucket) OVER (PARTITION BY browser), 4) AS is_product_bucket_share FROM scored WINDOW w_grp AS (ORDER BY is_product, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING)), daily AS (SELECT CASE WHEN device_min_is_product_avg_6 >= 77 THEN 'LARGE' ELSE 'SMALL' END AS device_min_is_product_avg_6_tier, COUNT(CASE WHEN country = 'US' THEN 1 END) AS us_count, SIZE(COLLECT_SET(web_event_event_type)) AS num_web_event_event_types, ROUND(SUM(device_min_is_product_avg_6) / NULLIF(COUNT(CASE WHEN web_event_event_type = 'add_to_cart' THEN 1 END), 0), 2) AS device_min_is_product_avg_6_per_add_to_cart, ROUND(SUM(device_min_is_product_avg_6) / NULLIF(COUNT(CASE WHEN country = 'US' THEN 1 END), 0), 2) AS device_min_is_product_avg_6_per_us, COUNT_IF(country = 'JP') AS jp_events FROM enriched GROUP BY 1) SELECT device_min_is_product_avg_6_tier, us_count, num_web_event_event_types, device_min_is_product_avg_6_per_add_to_cart, device_min_is_product_avg_6_per_us FROM daily;
